import heapq


def pass_route(n: int, edges: list[list[int]], stations: list[list[int]], prices: list[int]) -> int:
    zone_count = len(prices)
    state_count = 1 << zone_count

    adj = [[] for _ in range(n)]
    for u, v, cost, zone in edges:
        adj[u].append((v, cost, zone))
        adj[v].append((u, cost, zone))

    sales = [[] for _ in range(n)]
    for stop, zone in stations:
        if 0 <= zone < zone_count and zone not in sales[stop]:
            sales[stop].append(zone)

    inf = float("inf")
    dist = [[inf] * state_count for _ in range(n)]
    dist[0][0] = 0
    pq = [(0, 0, 0)]

    while pq:
        cost_so_far, u, mask = heapq.heappop(pq)
        if cost_so_far != dist[u][mask]:
            continue
        if u == n - 1:
            return cost_so_far

        for v, cost, zone in adj[u]:
            ride_cost = 0 if zone >= 0 and (mask >> zone) & 1 else cost
            new_cost = cost_so_far + ride_cost
            if new_cost < dist[v][mask]:
                dist[v][mask] = new_cost
                heapq.heappush(pq, (new_cost, v, mask))

        for zone in sales[u]:
            if not (mask >> zone) & 1:
                new_mask = mask | (1 << zone)
                new_cost = cost_so_far + prices[zone]
                if new_cost < dist[u][new_mask]:
                    dist[u][new_mask] = new_cost
                    heapq.heappush(pq, (new_cost, u, new_mask))

    return -1
